#!/bin/bash

# Read .env.test and convert to JSON
CONTENT=$(cat .env.test)

# Create JSON payload
JSON_PAYLOAD=$(cat <<EOF
{
  "content": "$(echo "$CONTENT" | sed ':a;N;$!ba;s/\n/\\n/g' | sed 's/"/\\"/g')"
}
EOF
)

echo "$JSON_PAYLOAD" > payload.json
echo "Payload created: payload.json"

